// Shared pieces of the farm tests (outcomes, projects, the queue, pools):
// a sliced two-plate project for a Klipper printer, and waiting helpers.
import { zip } from "./lib.mjs";

export const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

/** Poll `client.get(path)` until `ok(json)`, at most `tries` × 250 ms. */
export async function until(client, path, ok, tries = 80) {
  let v;
  for (let i = 0; i < tries; i++) {
    v = (await client.get(path)).json;
    if (ok(v)) return v;
    await sleep(250);
  }
  return v;
}

const gcode = (n) =>
  [
    "; generated by OrcaSlicer 2.4.2",
    `G1 X${n}0 Y10 E1`,
    "; total filament used [g] = 2.00",
    "; estimated printing time (normal mode) = 2s",
    "; filament_type = PLA",
    "; nozzle_diameter = 0.4",
    "; printer_model = Voron 2.4 350",
  ].join("\n");

/** A `.gcode.3mf` for a Voron: plate 1 holds three Brackets and a Clip,
 *  plate 2 one Clip. */
export function bracketsProject() {
  const sliceInfo = `<?xml version="1.0" encoding="UTF-8"?>
<config>
  <plate>
    <metadata key="index" value="1"/>
    <metadata key="weight" value="12.5"/>
    <object identify_id="1" name="Bracket" skipped="false"/>
    <object identify_id="2" name="Bracket" skipped="false"/>
    <object identify_id="3" name="Clip" skipped="false"/>
    <object identify_id="4" name="Bracket" skipped="false"/>
    <object identify_id="5" name="Spare" skipped="true"/>
    <filament id="1" type="PLA" color="#FF0000" used_g="12.5" used_m="4.1"/>
  </plate>
  <plate>
    <metadata key="index" value="2"/>
    <metadata key="weight" value="2"/>
    <object identify_id="6" name="Clip" skipped="false"/>
    <filament id="1" type="PLA" color="#FF0000" used_g="2" used_m="0.7"/>
  </plate>
</config>`;
  return zip({
    "Metadata/plate_1.gcode": gcode(1),
    "Metadata/plate_2.gcode": gcode(2),
    "Metadata/slice_info.config": sliceInfo,
    "Metadata/project_settings.config": JSON.stringify({ printer_model: "Voron 2.4 350" }),
  });
}

/** Add a Klipper printer on `fake` and wait for it to be idle. */
export async function addVoron(owner, fake, name = "Voron A") {
  const r = await owner.post("/api/printers", {
    name,
    machine_profile: "Voron 2.4 350",
    nozzle_diameter: "0.4",
    protocol: "moonraker",
    address: fake.address,
  });
  if (r.status !== 201) throw new Error(`can't add ${name}: ${JSON.stringify(r.json)}`);
  await until(owner, "/api/printers/status", (l) => l?.find((s) => s.printer_id === r.json.id)?.state === "IDLE");
  return r.json.id;
}

/** Wait until the printer can take another print. */
export async function printerFree(owner, id) {
  await until(owner, "/api/printers/status", (l) => ["IDLE", "FINISH", "CANCELLED", "FAILED"].includes(l?.find((s) => s.printer_id === id)?.state));
  await until(owner, `/api/prints?printer=${id}&active=1`, (l) => Array.isArray(l) && l.length === 0);
}
